const h = (hex) => ({ r: parseInt(hex.slice(1, 3), 16) / 255, g: parseInt(hex.slice(3, 5), 16) / 255, b: parseInt(hex.slice(5, 7), 16) / 255 })
const board = await figma.getNodeByIdAsync('182:7357')
const before = { w: board.width, h: board.height }
const origin = board.absoluteBoundingBox
const notes = [
  { id: '182:7366', note: 'No-show: set by the hotel, after a missed check-in', shift: -64 },
  { id: '182:7391', note: 'Cancelled: set by the guest, while Pending or Confirmed', shift: 64 },
]
const probe = figma.createSticky()
await figma.loadFontAsync(probe.text.fontName)
probe.remove()
let edge = 0
for (const c of board.children) {
  if (c.type === 'TEXT' || c.name === 'Key') continue
  const b = c.absoluteBoundingBox
  edge = Math.max(edge, b.x + b.width - origin.x)
}
const created = []
let right = 0, bottom = 0
for (let i = 0; i < notes.length; i++) {
  const box = (await figma.getNodeByIdAsync(notes[i].id)).absoluteBoundingBox
  const sticky = figma.createSticky()
  sticky.name = `note:${i + 1}`
  sticky.text.characters = notes[i].note
  sticky.fills = [{ type: 'SOLID', color: h('#A8DAFF') }]
  board.appendChild(sticky)
  sticky.x = Math.round((edge + 64) / 8) * 8
  sticky.y = Math.round((box.y - origin.y + box.height / 2 - sticky.height / 2 + notes[i].shift) / 8) * 8
  right = Math.max(right, sticky.x + sticky.width)
  bottom = Math.max(bottom, sticky.y + sticky.height)
  created.push(sticky.id)
}
board.resizeWithoutConstraints(Math.max(board.width, Math.ceil((right + 80) / 8) * 8), Math.max(board.height, Math.ceil((bottom + 80) / 8) * 8))
const stickies = await Promise.all(created.map((id) => figma.getNodeByIdAsync(id)))
const overlaps = []
for (const s of stickies) {
  const a = s.absoluteBoundingBox
  for (const c of board.children) {
    if (c.id === s.id) continue
    const b = c.absoluteBoundingBox
    if (a.x < b.x + b.width && b.x < a.x + a.width && a.y < b.y + b.height && b.y < a.y + a.height) overlaps.push(`${s.name} with ${c.name}`)
  }
}
await board.screenshot({ scale: Math.min(1, 1600 / board.width) })
return { createdNodeIds: created, boardBefore: before, boardAfter: { w: board.width, h: board.height }, positions: stickies.map((s) => ({ name: s.name, x: s.x, y: s.y, w: s.width, h: s.height })), overlaps }

